1	#include "SetupOptionsLoader.hpp"
2	
3	#include "libslic3r/Preset.hpp"
4	#include "libslic3r/PresetBundle.hpp"
5	#include "libslic3r/PrintConfig.hpp"
6	
7	#include <boost/algorithm/string/case_conv.hpp>
8	
9	#include <algorithm>
10	#include <set>
11	#include <stdexcept>
12	
13	namespace Slic3r::GUI::JusPrin::PrinterSetup {
14	
15	namespace {
16	
17	std::string first_of(const Preset& preset, const char* key)
18	{
19	    const auto* values = preset.config.option<ConfigOptionStrings>(key);
20	    return values != nullptr && !values->values.empty() ? values->values.front() : std::string();
21	}
22	
23	// The plates OrcaSlicer's sidebar lists for this printer, in its order:
24	// every BedType after Default, less the model's not_support_bed_type, which
25	// names them by label (Sidebar::reset_bed_type_combox_choices). The sidebar
26	// shows the list only for a Bambu Lab printer or one whose profile turns on
27	// support_multi_bed_types (Sidebar::update_presets); for any other printer it
28	// offers no choice, and neither does the form.
29	std::vector<PlateOption> plates_of(PresetBundle& bundle, const Preset& printer)
30	{
31	    std::vector<PlateOption> plates;
32	    const auto* multi = printer.config.option<ConfigOptionBool>("support_multi_bed_types");
33	    if (!bundle.is_bbl_vendor() && !(multi != nullptr && multi->value))
34	        return plates;
35	    const ConfigOptionDef*              definition = print_config_def.get("curr_bed_type");
36	    const VendorProfile::PrinterModel* model      = PresetUtils::system_printer_model(printer);
37	    int                                 type       = 0;
38	    for (const std::string& label : definition->enum_labels) {
39	        ++type;
40	        if (model != nullptr &&
41	            std::find(model->not_support_bed_types.begin(), model->not_support_bed_types.end(), label) !=
42	                model->not_support_bed_types.end())
43	            continue;
44	        plates.push_back(PlateOption{type, label});
45	    }
46	    return plates;
47	}
48	
49	} // namespace
50	
51	SetupOptions load_setup_options(const std::string& profiles_directory, const std::string& vendor_id,
52	                                const std::string& printer_preset)
53	{
54	    SetupOptions options;
55	    PresetBundle bundle;
56	    try {
57	        bundle.load_system_vendor_from_dir(profiles_directory, vendor_id, ForwardCompatibilitySubstitutionRule::EnableSilent);
58	    } catch (const std::runtime_error& error) {
59	        options.error = std::string("The printer profiles could not be read: ") + error.what();
60	        return options;
61	    }
62	
63	    const Preset* printer = bundle.printers.find_preset(printer_preset, false);
64	    if (printer == nullptr || printer->name != printer_preset)
65	        throw std::logic_error("The packaged profiles hold no printer profile \"" + printer_preset + "\"");
66	    // Selected as the sidebar's would be, so the vendor checks below read
67	    // this printer.
68	    bundle.printers.select_preset_by_name(printer_preset, true);
69	    Preset& selected = bundle.printers.get_edited_preset();
70	
71	    options.plates        = plates_of(bundle, selected);
72	    options.default_plate = int(selected.get_default_bed_type(&bundle));
73	
74	    // OrcaSlicer's own test, as its filament list applies it to the selected
75	    // printer: compatible_printers, the condition, and the library's
76	    // exclusions. One preset per shown name, as the list shows them.
77	    const PresetWithVendorProfile active = bundle.printers.get_edited_preset_with_vendor_profile();
78	    std::set<std::string>         labels;
79	    for (const Preset& filament : bundle.filaments) {
80	        if (filament.is_default || !filament.is_system)
81	            continue;
82	        if (!is_compatible_with_printer(bundle.filaments.get_preset_with_vendor_profile(filament), active))
83	            continue;
84	        const std::string label = filament.alias.empty() ? filament.name : filament.alias;
85	        if (!labels.insert(label).second)
86	            continue;
87	        options.filaments.push_back(FilamentOption{filament.name, label, first_of(filament, "filament_vendor"),
88	                                                   first_of(filament, "filament_type")});
89	    }
90	    std::sort(options.filaments.begin(), options.filaments.end(), [](const FilamentOption& a, const FilamentOption& b) {
91	        return boost::algorithm::to_lower_copy(a.label) < boost::algorithm::to_lower_copy(b.label);
92	    });
93	
94	    // A filament the profile names, as the compatible preset of the same
95	    // shown name: profiles often name one variant ("@BBL X1C") that the list
96	    // shows under its alias for every printer it fits.
97	    const auto compatible = [&bundle, &options](const std::string& name) -> std::string {
98	        const Preset* named = bundle.filaments.find_preset(name, false);
99	        if (named == nullptr)
100	            return {};
101	        const std::string label = named->alias.empty() ? named->name : named->alias;
102	        const auto        found = std::find_if(options.filaments.begin(), options.filaments.end(),
103	                                               [&label](const FilamentOption& option) { return option.label == label; });
104	        return found == options.filaments.end() ? std::string() : found->name;
105	    };
106	    if (const VendorProfile::PrinterModel* model = PresetUtils::system_printer_model(selected))
107	        for (const std::string& material : model->default_materials)
108	            if (const std::string name = compatible(material);
109	                !name.empty() && std::find(options.suggested.begin(), options.suggested.end(), name) == options.suggested.end())
110	                options.suggested.push_back(name);
111	    options.default_filament = compatible(first_of(selected, "default_filament_profile"));
112	    return options;
113	}
114	
115	} // namespace Slic3r::GUI::JusPrin::PrinterSetup
