                 [icon('plus', 'action-primary'), text('Create a filament preset…', 'body-small-bold', 'action-primary', 'flex:1 1 0;min-width:0;')],
                 comp='Menu/Row:State=Default')


def checkbox(on, count):
    box_style = ('background:var(--action-primary);box-shadow:inset 0 0 0 1px var(--action-primary)' if on else
                 'background:var(--surface-canvas);box-shadow:inset 0 0 0 1px var(--border-strong)')
    box = frame('box', f'width:16px;height:16px;margin-top:2px;border-radius:var(--radius-small);display:flex;justify-content:center;align-items:center;{box_style}',
                f'16x16 | fill {"action-primary" if on else "surface-canvas"} | border 1 inside {"action-primary" if on else "border-strong"} | radius 4 (radius-small)',
                [icon('check', 'action-on-primary', 12)] if on else [])
    sub = f'Picking one saves a copy for the {MODEL}.' if on else f'{count} more. Picking one saves a copy for the {MODEL}.'
    return frame('Show filaments made for other printers', 'align-self:stretch;display:flex;gap:var(--space-8);align-items:flex-start',
                 '(width fill, height hug) | row, start/start, gap 8',
                 [box, frame('Label', 'flex:1 1 0;min-width:0;display:flex;flex-direction:column;align-items:flex-start', '(width fill, height hug) | column, start/start',
                             [text('Show filaments made for other printers', 'body', 'text-primary'), text(sub, 'label', 'text-secondary')])],
                 comp=f'Checkbox:State={"Checked" if on else "Default"}')


def lead(bold, rest=''):
    kids = []
    o = f'<div class="body-small" style="{BOX}align-self:stretch;color:var(--text-secondary)">'
    inner = (f'<span class="body-small-bold" style="color:var(--text-primary)">{escape(bold)}</span>' if bold else '') + (' ' if bold and rest else '') + escape(rest)
    t = (bold + (' ' if bold and rest else '') + rest)
    n = Node(o + inner, '</div>', f'"{t}"  [text]  (width fill, height hug) | style body-small | color text-secondary' + (f' | "{bold}" in body-small-bold text-primary' if bold else ''))
    return n


def link(t):
    return frame(t, 'height:26px;display:flex;padding:0px var(--space-4) 0px var(--space-4);align-items:center;border-radius:var(--radius-small)',
                 '(width hug) x26 | row, start/center, padding 0 4 | radius 4 (radius-small)', [text(t, 'label-bold', 'action-primary', 'white-space:nowrap;', '(width hug, height hug)')],
                 comp='Button/Link:State=Normal')


def end_block(kids, flush=False):
    style = 'align-self:stretch;display:flex;flex-direction:column;gap:var(--space-8);align-items:flex-start;padding:var(--space-12) var(--space-12) 0px var(--space-12);margin-top:var(--space-8)'
    spec = '(width fill, height hug) | column, start/start, gap 8, padding 12 12 0 12'
    if not flush:
        style += ';box-shadow:inset 0 1px 0 0 var(--border-subtle)'
        spec += ' | border top 1 border-subtle'
    return frame('Not in the list' if not flush else 'Nothing found', style, spec, kids)


def listing(kids, height=None, at_end=False):
    clip = f'height:{height}px;overflow:hidden;' if height else ''
    clip += 'justify-content:flex-end;' if at_end else ''
    return frame('Filaments', f'align-self:stretch;margin:0px -12px;display:flex;flex-direction:column;gap:2px;{clip}',
